fn tokenize_unicode_string_literal(&self, chars: &mut State) -> Result<UnicodeStringLiteral, TokenizerError> {
    // scan the body, remembering the location of each char
    let mut raw: Vec<(char, Location)> = vec![];
    chars.next(); // consume the opening quote
    loop {
        let loc = chars.location();
        match chars.next() {
            Some('\'') => {
                if chars.peek() == Some(&'\'') {
                    raw.push(('\'', loc));
                    let loc2 = chars.location();
                    chars.next();
                    raw.push(('\'', loc2));
                } else {
                    break;
                }
            }
            Some(c) => raw.push((c, loc)),
            None => return Err(TokenizerError {
                message: "Unterminated unicode encoded string literal".to_string(),
                location: chars.location(),
            }),
        }
    }
    let escape = self.take_uescape_char(chars)?; // Option<char>
    let value = decode_unicode_escapes(&raw, escape.unwrap_or('\\'))?;
    Ok(UnicodeStringLiteral { value, escape })
}
