fn decode_unicode_escapes(raw: &[(char, Location)], escape: char) -> Result<String, TokenizerError> {
    let mut unescaped = String::new();
    let mut i = 0;
    while i < raw.len() {
        let (c, loc) = raw[i];
        match c {
            '\'' => {
                // a quote inside the body is always part of a '' pair
                debug_assert!(raw.get(i+1) == Some(&('\'', _)));
                unescaped.push('\'');
                i += 2;
            }
            c if c == escape => {
                match raw.get(i + 1) {
                    Some(&(next, _)) if next == escape => {
                        unescaped.push(escape);
                        i += 2;
                    }
                    Some(&('+', _)) => {
                        // 6 hex digits
                        let ch = take_char_from_hex_digits(raw, i + 2, 6, loc)?;
                        unescaped.push(ch);
                        i += 2 + 6;
                    }
                    _ => {
                        let ch = take_char_from_hex_digits(raw, i + 1, 4, loc)?;
                        unescaped.push(ch);
                        i += 1 + 4;
                    }
                }
            }
            _ => {
                unescaped.push(c);
                i += 1;
            }
        }
    }
    Ok(unescaped)
}
