/// Reads a Unicode string literal introduced by the `U&` prefix, e.g.
/// `U&'\0061\0062\0063'`, honoring an optional trailing `UESCAPE '<char>'`
/// clause that selects a custom escape character.
/// See <https://www.postgresql.org/docs/current/sql-syntax-lexical.html#SQL-SYNTAX-STRINGS-UESCAPE>
fn tokenize_unicode_string_literal(
    &self,
    chars: &mut State,
) -> Result<UnicodeStringLiteral, TokenizerError> {
    // Read the raw characters of the literal body, remembering the location
    // of each character so that escape sequence errors can be reported at
    // the exact start of the offending sequence.
    let mut raw = vec![];
    chars.next(); // consume the opening quote
    loop {
        let location = chars.location();
        match chars.next() {
            Some('\'') => {
                if chars.peek() == Some(&'\'') {
                    raw.push(('\'', location));
                    let location = chars.location();
                    chars.next();
                    raw.push(('\'', location));
                } else {
                    break;
                }
