            unescaped.push('\'');
            index += 2;
            continue;
        }
        if c != escape {
            unescaped.push(c);
            index += 1;
            continue;
        }
        match raw.get(index + 1) {
            Some((next, _)) if *next == escape => {
                unescaped.push(escape);
                index += 2;
            }
            Some(('+', _)) => {
                unescaped.push(take_char_from_hex_digits(raw, index + 2, 6, location)?);
                index += 8;
            }
            _ => {
                unescaped.push(take_char_from_hex_digits(raw, index + 1, 4, location)?);
                index += 5;
            }
        }
    }
