#[cfg(feature = "serde")]
impl serde::Serialize for UnicodeStringLiteral {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        // For compatibility with the previous serialization format, literals
        // without an explicit `UESCAPE` clause serialize as a plain string.
        match self.escape {
            Some(escape) => {
                use serde::ser::SerializeStruct;
                let mut state = serializer.serialize_struct("UnicodeStringLiteral", 2)?;
                state.serialize_field("value", &self.value)?;
                state.serialize_field("escape", &escape)?;
                state.end()
            }
            None => serializer.serialize_str(&self.value),
        }
    }
}

#[cfg(feature = "serde")]
impl<'de> serde::Deserialize<'de> for UnicodeStringLiteral {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(serde::Deserialize)]
        #[serde(untagged)]
        enum Repr {
            Legacy(String),
            WithEscape { value: String, escape: char },
        }
        Ok(match Repr::deserialize(deserializer)? {
            Repr::Legacy(value) => UnicodeStringLiteral { value, escape: None },
            Repr::WithEscape { value, escape } => UnicodeStringLiteral { value, escape: Some(escape) },
        })
    }
}
